/* Workflows: an editorial explanation and a local simulation, without external execution. */
const W_SCENARIOS=[
{label:'Uma mensagem',title:'Receber é só<br>o primeiro passo.',copy:'A conversa ganha contexto e encontra uma próxima ação. O fluxo deixa explícito o que deve acontecer entre uma etapa e outra.',nodes:['Mensagem recebida','Consultar o contato','Preparar resposta','Enviar pelo canal','Registrar continuidade'],groups:[[0],[1],[2],[3],[4]],notes:['A mensagem inicia este percurso. O contexto do canal acompanha a entrada.','O fluxo procura a referência do cliente para continuar com contexto.','A resposta é preparada conforme as orientações da operação.','O canal realiza o envio, respeitando suas regras e permissões.','O relacionamento recebe o registro necessário para a próxima conversa.'],blocks:[['wpp-business','Comunicação'],['customers','Relacionamento'],['ai-engine','Apoio à resposta']],missing:'Se o contato não tiver os dados necessários, a jornada encaminha a pendência para a equipe.',failure:'Se o canal não responder, a entrega precisa de tratamento. O registro da tentativa ajuda a equipe a decidir como retomar.'},
{label:'Uma proposta',title:'O trabalho pode se dividir.<br>O contexto continua junto.',copy:'Consultas independentes podem seguir em paralelo. A próxima etapa aguarda as informações de que precisa para continuar.',nodes:['Proposta recebida','Consultar cadastro','Consultar documentos','Reunir informações','Aplicar a política'],groups:[[0],[1,2],[3],[4]],notes:['A proposta inicia o fluxo com a referência da operação.','Duas consultas independentes acontecem lado a lado. Cada uma mantém sua responsabilidade.','O fluxo reúne os resultados antes de seguir para a avaliação.','A política usa o contexto reunido. O tratamento do resultado continua conforme as regras da operação.'],blocks:[['customers','Cadastro'],['file-storage','Documentos'],['decision-engine','Política']],missing:'Documento ausente é uma pendência. O produto precisa definir como coletá-lo ou pedir uma revisão, antes de prosseguir.',failure:'Se uma consulta falhar, informação incompleta não deve parecer resultado válido. O tratamento da exceção precisa estar previsto.'},
{label:'Um atendimento',title:'A conversa termina.<br>A continuidade começa.',copy:'O encerramento pode preparar um resumo e reunir os próximos passos. A liberação definida pela operação orienta o que vem depois.',nodes:['Conversa encerrada','Preparar resumo','Conferir o conteúdo','Liberar próximos passos','Atualizar a operação'],groups:[[0],[1],[2],[3],[4]],notes:['O encerramento é o ponto de partida deste exemplo. O uso do conteúdo depende da autorização.','A composição prepara um resumo para apoiar quem acompanhou a conversa.','A pessoa responsável confere o conteúdo e os encaminhamentos previstos.','A jornada continua conforme a liberação humana configurada no produto.','As capacidades selecionadas atualizam o contexto ou realizam as ações autorizadas.'],blocks:[['rooms','Encontro'],['ai-engine','Resumo'],['data-store','Contexto']],missing:'Se faltar contexto, o resumo pode precisar de complementação. A pessoa responsável deve conseguir revisar antes de liberar.',failure:'Uma ação indisponível não conclui o trabalho por aparência. A equipe precisa saber o que ficou pendente e como continuar.'}
];
Object.assign(X_CAPTURE_META,{
'workflows-canvas.jpg':{product:'workflows',title:'Canvas / Uma campanha ganha percurso',desc:'Editor visual com etapas, conexões e uma ramificação de campanha.',type:'Canvas',origin:'Captura preservada em apps/vitrine/src/assets/ss-canvas.jpg · data original não informada'},
'workflows-detail.png':{product:'workflows',title:'Configuração / Gatilhos, ações e validação',desc:'Interface de configuração de um fluxo de teste, com seus pontos de entrada e passos.',type:'Configuração',origin:'Baseline de interface de 30/07/2026 · fluxo de teste · não é indicador de cliente'}
});
function wHeroArt(){return `<svg class="w-hero-art w-hero-architecture" viewBox="0 0 760 640" role="img" aria-label="Três planos de trabalho ligados por uma conexão contínua: entrada, organização e resultado"><defs><linearGradient id="wf-plane" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e7d9f0"/><stop offset="1" stop-color="#b89acc"/></linearGradient><linearGradient id="wf-orange" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffc183"/><stop offset="1" stop-color="#e98c48"/></linearGradient><filter id="wf-soft"><feGaussianBlur stdDeviation="15"/></filter></defs><ellipse cx="399" cy="500" rx="240" ry="43" fill="#160c1d" opacity=".4" filter="url(#wf-soft)"/><g stroke="#79558f" stroke-width=".65" fill="none" opacity=".6"><path d="M70 430L374 254L690 437L386 612Z"/><path d="M148 475L452 299M228 520L531 345M305 566L610 391M147 385L463 568M223 342L539 524M300 299L616 481" stroke-dasharray="2 8"/></g><g class="w-assembly-left"><path d="M100 345L220 276L340 345L220 415Z" fill="#a180b7"/><path d="M100 345V377L220 447V415Z" fill="#77528e"/><path d="M220 415L340 345V377L220 447Z" fill="#4e2f64"/><path d="M146 250L242 194L242 326L146 382Z" fill="url(#wf-plane)"/><path d="M242 194L257 203V335L242 326Z" fill="#8e6ba6"/><path d="M166 265L222 233M166 287L222 255M166 309L208 285" stroke="#a789bc" stroke-width="1.3"/><circle cx="193" cy="339" r="5" fill="#f5c35b"/></g><g class="w-assembly-middle"><path d="M286 390L406 320L526 390L406 460Z" fill="#c6acda"/><path d="M286 390V416L406 486V460Z" fill="#946dac"/><path d="M406 460L526 390V416L406 486Z" fill="#64437d"/><path d="M339 232L439 174L439 358L339 416Z" fill="url(#wf-orange)"/><path d="M439 174L456 184V368L439 358Z" fill="#c66e34"/><path d="M361 248L418 215V292L361 325Z" fill="#744688"/><path d="M361 248L372 255V319L361 325Z" fill="#9c5c36"/><path d="M373 256L418 230V292L373 318Z" fill="#35223f"/><path d="M361 352L418 319" stroke="#f8c692" stroke-width="2"/></g><g class="w-assembly-right"><path d="M460 323L580 254L700 323L580 392Z" fill="#cbb6da"/><path d="M460 323V352L580 421V392Z" fill="#9874b1"/><path d="M580 392L700 323V352L580 421Z" fill="#70498c"/><path d="M510 190L608 134L608 290L510 347Z" fill="#ddcbe9"/><path d="M608 134L622 142V298L608 290Z" fill="#a788bb"/><path d="M532 222L588 190M532 244L588 212M532 266L574 242" stroke="#ae8cc3" stroke-width="1.3"/><circle cx="558" cy="291" r="14" fill="#8b62a6"/><path d="M551 291L557 297L568 279" fill="none" stroke="#f5eafc" stroke-width="1.6"/></g><g fill="none"><path d="M191 390L298 452L397 395L465 434L572 372" stroke="#805493" stroke-width="9"/><path d="M191 385L298 447L397 390L465 429L572 367" stroke="#e9a065" stroke-width="4"/><path class="w-hero-current" d="M191 385L298 447L397 390L465 429L572 367" stroke="#ffe0b4" stroke-width="1.5" stroke-dasharray="3 15"/></g><g fill="#ad8abf" font-family="monospace" font-size="9" letter-spacing="2"><text x="117" y="490">01 / ENTRADA</text><text x="308" y="535">02 / PERCURSO</text><text x="527" y="463">03 / CONTINUIDADE</text></g></svg>`}
function wDiagram(i,step=0,mode='regular'){const s=W_SCENARIOS[i],active=new Set(s.groups[step]),done=new Set(s.groups.slice(0,step).flat()),parallel=i===1,positions=parallel?[[390,52],[195,172],[585,172],[390,302],[390,425]]:[[95,70],[290,70],[500,175],[290,280],[95,385]];const paths=parallel?['M390 82V112H195V142','M390 112H585V142','M195 202V252H390V272','M585 202V252H390','M390 332V395']:['M165 70H220','M360 70H430Q500 70 500 145','M500 205V250Q500 280 360 280','M220 280H95V355'];return `<svg viewBox="0 0 780 500" class="w-flow-diagram" role="img" aria-label="Percurso ilustrativo: ${ce(s.nodes.join(', '))}"><g fill="none" stroke="#c7b2d3" stroke-width="2">${paths.map(p=>`<path d="${p}"/>`).join('')}</g>${mode==='regular'?'':`<path d="${parallel?'M390 332H635V425':'M360 280H640V385'}" fill="none" stroke="#d38a54" stroke-width="2" stroke-dasharray="5 6"/><g><rect x="550" y="${parallel?395:355}" width="180" height="60" rx="3" fill="#efba87"/><text x="640" y="${parallel?430:390}" text-anchor="middle" font-family="Inter,sans-serif" font-size="13" fill="#65412e">${mode==='missing'?'Pedir complementação':'Tratar a exceção'}</text></g>`}${positions.map(([x,y],j)=>{const isActive=active.has(j),isDone=done.has(j);return `<g class="${isActive?'w-node-current':''}"><rect x="${x-70}" y="${y-30}" width="140" height="60" rx="${j===0||j===4?30:3}" fill="${isActive?'#79529a':isDone?'#d5c3e2':'#f8f4fb'}" stroke="${isActive?'#79529a':'#cfb9dc'}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-family="Inter,sans-serif" font-size="11" fill="${isActive?'#fff7ff':'#866395'}">${ce(s.nodes[j])}</text><text x="${x}" y="${y-42}" text-anchor="middle" font-family="monospace" font-size="8" fill="#b29ac1">${isDone?'PERCORRIDO':isActive?'EM FOCO':'0'+(j+1)}</text></g>`}).join('')}</svg>`}
function wSimulation(i=0,step=0,mode='regular'){const s=W_SCENARIOS[i],note=mode==='missing'?s.missing:mode==='failure'?s.failure:s.notes[step];return `<div class="w-simulation-top"><div><span class="label">Simulação conceitual / ${s.label}</span><h3>${s.title}</h3><p>${s.copy}</p></div><label>Caminho para explorar<select id="w-sim-mode"><option value="regular" ${mode==='regular'?'selected':''}>Percurso regular</option><option value="missing" ${mode==='missing'?'selected':''}>Informação ausente</option><option value="failure" ${mode==='failure'?'selected':''}>Integração indisponível</option></select></label></div><div class="w-simulation-body"><div class="w-diagram-scroll">${wDiagram(i,step,mode)}<span class="w-mobile-hint">Deslize para explorar o percurso ↔</span></div><aside class="w-simulation-reading"><span>ETAPA ${step+1} / ${s.groups.length}</span><h4>${mode==='regular'?(i===1&&step===1?'Duas consultas, em paralelo.':s.nodes[s.groups[step][0]]):mode==='missing'?'Falta algo para seguir.':'O caminho precisa de atenção.'}</h4><p role="status">${note}</p><div class="w-simulation-buttons"><button data-w-prev ${step===0?'disabled':''} aria-label="Etapa anterior">←</button><button data-w-next>${step===s.groups.length-1?'Recomeçar':'Próxima etapa'} <span>→</span></button></div><small>Esta demonstração não executa operações. Os caminhos de revisão e recuperação precisam ser desenhados e validados no produto.</small></aside></div><div class="w-simulation-blocks"><span>Capacidades neste exemplo</span>${s.blocks.map(([slug,title])=>`<a href="/capacidades/${slug}/">${title} ↗</a>`).join('')}</div>`}
function wCapture(file,title,copy,origin){return `<figure class="w-print"><div class="w-print-title"><span>${title}</span><small>Ampliar ↗</small></div><button data-gallery-file="${file}" data-gallery-product="workflows" aria-label="Ampliar ${title}"><img src="/assets/screens/${file}" alt="${ce(copy)}" loading="lazy"></button><figcaption><p>${copy}</p><span>${origin}</span></figcaption></figure>`}
function wPage(){return `<div class="w-page"><section class="w-hero"><div class="wrap"><div><span class="label">Catalisa Workflows / O trabalho em movimento</span><h1>O próximo passo<br>tem um<br><em>porquê.</em></h1><p>Conecte acontecimentos, informações e ações em um percurso que a equipe consegue entender e acompanhar.</p><a href="#percursos" class="text-link">Explore um fluxo por dentro ↓</a></div><div class="w-hero-drawing">${wHeroArt()}</div></div><div class="w-hero-baseline wrap"><span>Uma entrada. Caminhos com contexto. Continuidade.</span><button data-w-motion aria-pressed="false">Ⅱ Pausar movimento</button></div></section><section class="w-definition wrap"><div><span class="label">O que é um workflow</span><h2>Uma forma de dizer<br><em>o que acontece depois.</em></h2></div><div><p>Uma mensagem chega. Uma proposta muda. Um horário é alcançado. O workflow conecta esse início às ações que precisam acontecer em seguida.</p><p>Ele organiza a ordem, as condições e as informações que cada passo utiliza. As capacidades fazem o trabalho; o fluxo dá sentido às conexões.</p><p class="w-definition-line">O produto encontra continuidade entre um acontecimento e o próximo.</p></div></section><section class="w-starters"><div class="wrap"><div><span class="label">O começo tem muitas formas</span><h2>O que põe<br>a jornada<br>em movimento?</h2></div><div class="w-starter-index">${[['Uma conversa','Uma mensagem recebida pode iniciar o atendimento ou continuar uma jornada.','01'],['Uma mudança','Um cadastro, uma proposta ou um sistema externo informa que algo aconteceu.','02'],['Um momento','Uma programação inicia uma rotina no momento definido pela operação.','03'],['Uma pessoa','A equipe pode iniciar um fluxo sob demanda, conforme sua permissão.','04']].map(([t,p,n])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="w-playground wrap" id="percursos"><div class="w-section-heading"><div><span class="label">Entender percorrendo</span><h2>Uma lógica que<br>dá para acompanhar.</h2></div><p>Escolha uma jornada, avance pelas etapas<br>e explore o que muda diante de uma exceção.</p></div><div class="w-scenario-tabs" role="tablist" aria-label="Exemplos de workflows">${W_SCENARIOS.map((s,i)=>`<button role="tab" id="w-scenario-${i}" data-w-scenario="${i}" aria-controls="w-simulation" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${s.label}</button>`).join('')}</div><div id="w-simulation" role="tabpanel" aria-labelledby="w-scenario-0">${wSimulation()}</div></section><section class="w-rhythm"><div class="wrap"><div class="w-rhythm-heading"><span class="label">Cada conexão tem sua lógica</span><h2>Esperar quando precisa.<br>Avançar quando pode.</h2><p>Nem todo trabalho é uma fila única. A relação entre as etapas define o percurso.</p></div><div class="w-rhythm-types"><article><div class="w-mini w-mini-sequence" aria-hidden="true"><i></i><i></i><i></i></div><h3>Em sequência</h3><p>Uma etapa usa o resultado da anterior. Primeiro encontrar o contato; depois atualizar o contexto.</p></article><article><div class="w-mini w-mini-parallel" aria-hidden="true"><i></i><i></i><i></i></div><h3>Em paralelo</h3><p>Consultas independentes podem acontecer lado a lado. A etapa seguinte aguarda o que realmente utiliza.</p></article><article><div class="w-mini w-mini-branch" aria-hidden="true"><i></i><i></i><i></i></div><h3>Por condição</h3><p>O contexto orienta o caminho. Um dado ausente pode exigir complementação; uma regra pode mudar o destino.</p></article></div></div></section><section class="w-editor"><div class="wrap"><div class="w-section-heading"><div><span class="label">A interface do percurso</span><h2>As conexões saem<br>da cabeça de uma pessoa.</h2></div><p>O editor visual torna a composição visível.<br>A configuração explicita como cada etapa participa.</p></div><div class="w-editor-main">${wCapture('workflows-canvas.jpg','Canvas / Ver as conexões','Uma campanha reúne programação, preparação e envio em um percurso visual.','Material da vitrine Catalisa · data original não informada')}</div><div class="w-editor-secondary"><div><span class="label">Configurar também é esclarecer</span><h3>O que inicia.<br>O que cada passo faz.<br>Como conferir.</h3><p>A configuração reúne os pontos de entrada e as ações da jornada. Conferir parâmetros e dependências faz parte da construção, antes de ampliar seu uso.</p>${ca('/studio/','Veja como o Studio ajuda a construir')}</div>${wCapture('workflows-detail.png','Configuração / Conferir a jornada','Tela de configuração e validação preservada no repositório, com um fluxo de teste.','Baseline de interface · 30/07/2026 · valores de demonstração')}</div><p class="w-editor-source">As capturas são referências de interfaces do repositório. Não representam uma execução ao vivo nem disponibilidade integral de integrações.</p></div></section><section class="w-context wrap"><div><span class="label">Informação que acompanha o trabalho</span><h2>O próximo passo<br>não começa<br><em>sem contexto.</em></h2><p>A informação produzida em uma etapa pode ser usada na próxima: o contato encontrado, o documento recebido ou o resultado de uma avaliação.</p></div><div class="w-context-example"><span>UM EXEMPLO SIMPLES</span><div><small>A entrada traz</small><strong>Uma mensagem</strong></div><div><small>A consulta encontra</small><strong>O contato</strong></div><div><small>A ação utiliza</small><strong>O contexto do atendimento</strong></div><p>É a conexão entre as informações que permite continuar a jornada, sem pedir tudo novamente a cada etapa.</p></div></section><section class="w-care"><div class="wrap"><div><span class="label">Continuidade com responsabilidade</span><h2>O fluxo precisa<br>explicar também<br>o que não deu certo.</h2><p>Entender o caminho regular é metade do trabalho. A outra metade é preparar a operação para o que foge dele.</p>${ca('/governanca/','Conecte fluxo e governança')}</div><div>${[['Dado ausente','Defina o que impede a continuidade e como a equipe pode completar o contexto.'],['Serviço indisponível','Preveja o tratamento da falha. Uma ação sem confirmação não deve aparecer como concluída.'],['Ação sensível','Permissões, autorizações e revisões pertencem ao desenho da jornada.'],['Mudança de regra','Valide o comportamento e o impacto antes de ampliar a nova configuração.']].map(([t,p],i)=>`<article><span>0${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></article>`).join('')}</div></div></section><section class="w-questions wrap"><div><span class="label">Para entender a composição</span><h2>Perguntas que<br>abrem caminho.</h2></div><div>${[
['Qual é a diferença entre um workflow e um agente?','O workflow organiza o percurso entre ações. Um agente pode interpretar o contexto e usar ferramentas dentro desse percurso, conforme as instruções e permissões definidas. Um não precisa assumir todas as responsabilidades do outro.'],
['O fluxo precisa usar IA?','Não. Consultas, condições, atualizações e notificações podem compor uma jornada sem interpretação por IA. Ela entra quando acrescenta valor a uma etapa e tem limites claros.'],
['Posso conectar sistemas que já uso?','Uma composição pode consultar serviços externos e aproveitar capacidades existentes. O funcionamento depende das integrações disponíveis, do acesso autorizado e dos contratos de cada sistema.'],
['O paralelo significa executar tudo ao mesmo tempo?','Apenas etapas independentes podem avançar lado a lado. Uma ação que precisa do resultado de outra aguarda essa dependência. É essa relação que organiza o percurso.'],
['Um fluxo resolve sozinho a revisão humana?','A revisão precisa ser parte explícita da experiência e da operação. Defina onde a pessoa participa, o que ela aprova e como o resultado dessa liberação chega ao restante da jornada.'],
['Por onde começo?','Escolha uma rotina com início e resultado claros. Identifique os participantes, os dados e as exceções. Estruture no Studio e valide a jornada completa antes de ampliar seu uso.']
].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">＋</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="w-closing"><div class="wrap"><span class="label">O trabalho encontra continuidade</span><h2>Conecte as peças.<br>Dê sentido ao percurso.</h2><div>${ca('/studio/','Conheça o Studio')}${ca('/capacidades/','Explore as capacidades')}${ca('/lab/','Imagine seu produto')}</div><span class="w-closing-line" aria-hidden="true"></span></div></section></div>`}
const wOriginalPage=cPage;cPage=function(route,blocks){return route==='/workflows/'?wPage():wOriginalPage(route,blocks)};
function wBind(){const root=document.querySelector('.w-page');if(!root)return;let scenario=0,step=0,mode='regular';const panel=document.getElementById('w-simulation');const render=()=>{panel.innerHTML=wSimulation(scenario,step,mode);panel.setAttribute('aria-labelledby','w-scenario-'+scenario)};const tabs=[...root.querySelectorAll('[data-w-scenario]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{scenario=i;step=0;mode='regular';tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});render()});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();tabs[n].focus()})});panel.addEventListener('click',e=>{if(e.target.closest('[data-w-next]')){step=(step+1)%W_SCENARIOS[scenario].groups.length;render();panel.querySelector('[data-w-next]').focus({preventScroll:true})}if(e.target.closest('[data-w-prev]')){step=Math.max(0,step-1);render();panel.querySelector('[data-w-prev]').focus({preventScroll:true})}});panel.addEventListener('change',e=>{if(e.target.id==='w-sim-mode'){mode=e.target.value;render();panel.querySelector('#w-sim-mode').focus({preventScroll:true})}});root.querySelector('[data-w-motion]').addEventListener('click',e=>{const paused=root.classList.toggle('w-motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▶ Retomar movimento':'Ⅱ Pausar movimento'})}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',wBind);
